namespace XPScript.Compiler;

internal static class NotesModifiedDocumentsPostProcessor
{
    public static string ApplyBuiltSurface(string source)
    {
        ArgumentNullException.ThrowIfNull(source);

        source = ReplaceRequired(
            source,
            "    public XPScriptNotesDocumentCollection CreateDocumentCollection()\n    {\n        EnsureAlive();\n        if (!IsOpen) throw new XPScriptRuntimeException(91, \"NotesDatabase is not open.\");\n        return new XPScriptNotesDocumentCollection(Session, this, []);\n    }",
            "    public XPScriptNotesDocumentCollection CreateDocumentCollection()\n    {\n        EnsureAlive();\n        if (!IsOpen) throw new XPScriptRuntimeException(91, \"NotesDatabase is not open.\");\n        return new XPScriptNotesDocumentCollection(Session, this, []);\n    }\n\n    public XPScriptNotesDocumentCollection? GetModifiedDocuments() => GetModifiedDocuments(null, 1);\n\n    public XPScriptNotesDocumentCollection? GetModifiedDocuments(object? sinceValue) => GetModifiedDocuments(sinceValue, 1);\n\n    public XPScriptNotesDocumentCollection? GetModifiedDocuments(object? sinceValue, object? noteClassValue)\n    {\n        EnsureAlive();\n        if (!IsOpen) return null;\n\n        var noteClass = noteClassValue is null || XPScriptNullRuntime.IsNull(noteClassValue)\n            ? 1\n            : XPScriptRuntime.CInt(noteClassValue);\n        const int supportedClasses = 0x0F5D;\n        if (noteClass != 0x7FFF && (noteClass <= 0 || (noteClass & ~supportedClasses) != 0))\n            throw new XPScriptRuntimeException(5, \"GetModifiedDocuments noteClass must be DBMOD_DOC_DATA, FORM, VIEW, ICON, ACL, HELP, AGENT, SHAREDFIELD, REPLFORMULA, DBMOD_DOC_ALL, or a bitwise combination of the supported class values.\");\n\n        XPScriptNotesTimeDate? since = null;\n        if (sinceValue is not null && !XPScriptNullRuntime.IsNull(sinceValue))\n        {\n            if (sinceValue is not XPScriptNotesDateTime dateTime)\n                throw new XPScriptRuntimeException(13, \"GetModifiedDocuments since must be a NotesDateTime or Nothing.\");\n            since = dateTime.NativeValue;\n        }\n\n        var modified = Session.Api.GetModifiedNoteIds(Handle, checked((ushort)noteClass), since);\n        var collection = new XPScriptNotesDocumentCollection(Session, this, modified.NoteIds);\n        collection.InitializeModifiedMetadata(modified.UntilTime, modified.DocumentNoteIds, modified.DesignNoteIds);\n        return collection;\n    }",
            "database-get-modified-documents");

        source = ReplaceRequired(
            source,
            "    private uint[] _noteIds;\n    private readonly string _replicaId;\n    private int _lastFetchedIndex = -1;\n    private uint _lastFetchedNoteId;",
            "    private uint[] _noteIds;\n    private readonly string _replicaId;\n    private int _lastFetchedIndex = -1;\n    private uint _lastFetchedNoteId;\n    private bool _hasModifiedMetadata;\n    private XPScriptNotesTimeDate _untilTime;\n    private uint[]? _documentNoteIds;\n    private uint[]? _designNoteIds;",
            "document-collection-modified-fields");

        source = ReplaceRequired(
            source,
            "    public XPScriptNotesDatabase Parent { get { EnsureAlive(); return Database; } }\n    internal uint[] NativeNoteIds { get { EnsureAlive(); return _noteIds.ToArray(); } }\n    public int Count { get { EnsureAlive(); return _noteIds.Length; } }",
            "    public XPScriptNotesDatabase Parent { get { EnsureAlive(); return Database; } }\n\n    internal void InitializeModifiedMetadata(XPScriptNotesTimeDate untilTime, IEnumerable<uint> documentNoteIds, IEnumerable<uint> designNoteIds)\n    {\n        _untilTime = untilTime;\n        _documentNoteIds = documentNoteIds.Distinct().ToArray();\n        _designNoteIds = designNoteIds.Distinct().ToArray();\n        _hasModifiedMetadata = true;\n    }\n\n    private XPScriptNotesDocumentCollection CreateModifiedSubset(uint[] noteIds, bool documents)\n    {\n        var subset = new XPScriptNotesDocumentCollection(Session, Database, noteIds);\n        subset.InitializeModifiedMetadata(_untilTime, documents ? noteIds : [], documents ? [] : noteIds);\n        return subset;\n    }\n\n    public XPScriptNotesDateTime? UntilTime\n    {\n        get\n        {\n            EnsureAlive();\n            return _hasModifiedMetadata ? XPScriptNotesDateTime.FromNative(Session, _untilTime) : null;\n        }\n    }\n\n    public XPScriptNotesDocumentCollection Documents\n    {\n        get\n        {\n            EnsureAlive();\n            EnsureModifiedMetadata();\n            return CreateModifiedSubset(_documentNoteIds!, true);\n        }\n    }\n\n    public XPScriptNotesDocumentCollection DesignElements\n    {\n        get\n        {\n            EnsureAlive();\n            EnsureModifiedMetadata();\n            return CreateModifiedSubset(_designNoteIds!, false);\n        }\n    }\n\n    private void EnsureModifiedMetadata()\n    {\n        if (_hasModifiedMetadata && _documentNoteIds is not null && _designNoteIds is not null) return;\n        throw new XPScriptRuntimeException(5, \"Documents and DesignElements are available on collections returned by NotesDatabase.GetModifiedDocuments.\");\n    }\n\n    internal uint[] NativeNoteIds { get { EnsureAlive(); return _noteIds.ToArray(); } }\n    public int Count { get { EnsureAlive(); return _noteIds.Length; } }",
            "document-collection-modified-properties");

        source = ReplaceRequired(
            source,
            "    internal ushort GetNoteClass(uint note)",
            "    internal (uint[] NoteIds, uint[] DocumentNoteIds, uint[] DesignNoteIds, XPScriptNotesTimeDate UntilTime) GetModifiedNoteIds(nint database, ushort noteClassMask, XPScriptNotesTimeDate? since)\n    {\n        EnsureInitialized();\n        using var formulaText = ToLmbcs(\"@All\");\n        var compileStatus = Resolve<NSFFormulaCompileDelegate>(\"NSFFormulaCompile\")(\n            0, 0, formulaText.Pointer, checked((ushort)formulaText.Length),\n            out var formulaHandle, out _, out var compileError, out var errorLine, out var errorColumn, out _, out _);\n        if (compileStatus != 0 || compileError != 0)\n        {\n            if (formulaHandle != 0) Resolve<OSMemFreeDelegate>(\"OSMemFree\")(formulaHandle);\n            var code = compileStatus != 0 ? compileStatus : compileError;\n            throw new XPScriptRuntimeException(5, \"Notes modified-note formula compilation failed at line \" + errorLine + \", column \" + errorColumn + \" (0x\" + code.ToString(\"X4\", System.Globalization.CultureInfo.InvariantCulture) + \".\");\n        }\n\n        const ushort documentClass = 0x0001;\n        const ushort designClasses = 0x0FBE;\n        var ids = new List<uint>();\n        var documents = new List<uint>();\n        var design = new List<uint>();\n        NSFSearchProcDelegate callback = (_, matchPointer, _) =>\n        {\n            if (matchPointer == 0) return 0;\n            var match = System.Runtime.InteropServices.Marshal.PtrToStructure<XPScriptNotesSearchMatch>(matchPointer);\n            if ((match.SERetFlags & SearchMatchFlag) == 0 || match.Id.NoteId == 0) return 0;\n            ids.Add(match.Id.NoteId);\n            if ((match.NoteClass & documentClass) != 0) documents.Add(match.Id.NoteId);\n            if ((match.NoteClass & designClasses) != 0) design.Add(match.Id.NoteId);\n            return 0;\n        };\n\n        var untilPointer = System.Runtime.InteropServices.Marshal.AllocHGlobal(System.Runtime.InteropServices.Marshal.SizeOf<XPScriptNotesTimeDate>());\n        nint sincePointer = 0;\n        try\n        {\n            System.Runtime.InteropServices.Marshal.StructureToPtr(default(XPScriptNotesTimeDate), untilPointer, false);\n            if (since.HasValue)\n            {\n                sincePointer = System.Runtime.InteropServices.Marshal.AllocHGlobal(System.Runtime.InteropServices.Marshal.SizeOf<XPScriptNotesTimeDate>());\n                System.Runtime.InteropServices.Marshal.StructureToPtr(since.Value, sincePointer, false);\n            }\n            var searchStatus = Resolve<NSFSearchDelegate>(\"NSFSearch\")(database, formulaHandle, 0, 0, noteClassMask, sincePointer, callback, 0, untilPointer);\n            Check(searchStatus, \"NSFSearch(modified notes)\");\n            var until = System.Runtime.InteropServices.Marshal.PtrToStructure<XPScriptNotesTimeDate>(untilPointer);\n            return (ids.Distinct().ToArray(), documents.Distinct().ToArray(), design.Distinct().ToArray(), until);\n        }\n        finally\n        {\n            if (sincePointer != 0) System.Runtime.InteropServices.Marshal.FreeHGlobal(sincePointer);\n            System.Runtime.InteropServices.Marshal.FreeHGlobal(untilPointer);\n            Resolve<OSMemFreeDelegate>(\"OSMemFree\")(formulaHandle);\n            GC.KeepAlive(callback);\n        }\n    }\n\n    internal ushort GetNoteClass(uint note)",
            "native-modified-note-helper");

        return source;
    }

    private static string ReplaceRequired(string source, string oldValue, string newValue, string stage)
    {
        if (!source.Contains(oldValue, StringComparison.Ordinal))
            throw new CompilerException("Unable to apply modified Notes document surface (" + stage + ").");
        return source.Replace(oldValue, newValue, StringComparison.Ordinal);
    }
}
